-- ============================================================
--  Neckline — demo/storefront seed data
--
--  Brand-safe, reusable snapshot of the Neckline demo store.
--  Restores: categories, products, product media references,
--  product↔category relations, Noir homepage/CMS content,
--  Noir layout settings, and store settings.
--
--  Contains NO users, sessions, accounts, orders, payments,
--  analytics, tracking, webhooks, promo codes, or secrets.
--
--  Media files live alongside this file in ./media/ and must be
--  copied into <repo-root>/uploads/ — see README.md.
--
--  Idempotent: every statement uses ON CONFLICT DO NOTHING, so
--  re-running will not duplicate or overwrite existing rows.
--
--  Requires: schema already migrated. The default store vendor
--  row is included below, so this restores into a database that
--  has never booted the server.
-- ============================================================

BEGIN;

